contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public {
        require(amount == 0);
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;
        assert(c.depositsCount() == countBefore && address(c).balance == balBefore);
    }
    receive() external payable {
        revert();
    }
}

